package com.audiobookdownloader;
import org.junit.*;import static org.junit.Assert.*;import java.util.*;
public class SeriesMetadataTest {
 private String fixture(String name)throws Exception{return new String(getClass().getResourceAsStream("/series-metadata/"+name+".html").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}
 @Test public void recordedMetadataDistinguishesDirectSeriesFromSourceWorld()throws Exception {var ref=SeriesAuthorityParser.detail(fixture("at-gold"),"https://author.today/work/72647");assertEquals("Хранитель кладов",ref.seriesTitle);var members=SeriesAuthorityParser.members(fixture("at-series"),ref.seriesUrl,ref.seriesTitle);assertEquals(4,members.size());assertEquals(2d,members.get(1).order,0);var source=KnigobludSeriesParser.detail(fixture("kb-gold"),"https://knigoblud.club/9b6d5bcd-ca40-4059-9ad8-9dbe3b12125c");assertEquals("Отдел 15-К",source.series);assertEquals("Андрей Васильев",source.author);assertTrue(source.books.size()>members.size());assertEquals(24,LitresReleaseParser.feed(fixture("litres-feed")).size());}
 @Test public void recordedHotelIncludesTheBoldCurrentBookAndItsSecondVolume()throws Exception{var hotel=KnigobludSeriesParser.detail(fixture("kb-hotel"),"https://knigoblud.club/c0b3325b-f922-4ae2-bfc0-9eb9acc5ab09");assertEquals(2,hotel.books.size());assertEquals("Отель Перекресток",hotel.books.get(0).title);assertEquals("Отель Перекресток. Том 2",hotel.books.get(1).title);assertTrue(LocalSeriesRules.sourceCycleConsistent(hotel.series,hotel.title,hotel.books));var world=KnigobludSeriesParser.detail(fixture("kb-gold"),"https://knigoblud.club/9b6d5bcd-ca40-4059-9ad8-9dbe3b12125c");assertFalse(LocalSeriesRules.sourceCycleConsistent(world.series,world.title,world.books));}
 private final String work="https://author.today/work/72647",cycle="https://author.today/work/series/7666";
 private String detail="<h1>Золото мертвых</h1><div class='book-meta-panel'><div class='book-authors'><span itemprop='author'><meta itemprop='name' content='Андрей Васильев'></span></div><div><a href='/work/series/7666'>Хранитель кладов</a><span>#2</span></div></div><aside><a href='/work/series/1'>Чужая серия</a></aside>";
 @Test public void ownMetadataWinsOverRecommendations(){var r=SeriesAuthorityParser.detail(detail,work);assertEquals("Хранитель кладов",r.seriesTitle);assertEquals(2d,r.order,0);assertTrue(SeriesAuthorityParser.matches("Золото мертвых","Андрей Васильев",r));assertFalse(SeriesAuthorityParser.matches("Золото мертвых","Другой Автор",r));}
 @Test public void parentWorldRemainsSeparate(){String url="https://www.litres.ru/audiobook/andrey-vasilev-4/zoloto-mertvyh-57100363/";var r=SeriesAuthorityParser.detail("<h1>Золото мертвых</h1><a data-testid='book__author--link'>Андрей Васильев</a><div data-testid='book__series--title'><a href='/series/hranitel-kladov-714498/'>2 книга из 4 в серии «Хранитель кладов»</a></div>",url);var p=SeriesAuthorityParser.parent("<h1>Хранитель кладов</h1><div data-testid='series__header--parent'><a href='/series/otdel-15-k-714506/'>Отдел 15-К</a></div>",r.seriesUrl,r);assertEquals("Хранитель кладов",p.seriesTitle);assertEquals("Отдел 15-К",p.parentTitle);}
 @Test public void directSeriesListUsesExplicitPositions(){var rows=SeriesAuthorityParser.members("<h1>Хранитель кладов</h1><div class='book-row-content'><div class='book-title'><span class='label-row-index'>2</span><a href='/work/72647'>Золото мертвых</a></div><div class='book-author'><a>Андрей Васильев</a></div></div>",cycle,"Хранитель кладов");assertEquals(1,rows.size());assertEquals(2d,rows.get(0).order,0);}
 @Test(expected=IllegalArgumentException.class)public void noGuessWithoutExplicitCycle(){SeriesAuthorityParser.detail("<h1>Золото мертвых</h1><div class='book-meta-panel'><div class='book-authors'><a>Андрей Васильев</a></div></div><aside><a href='/work/series/7666'>Хранитель кладов</a></aside>",work);}
 @Test public void whatsNewOnlyAfterAnUnacknowledgedUpdate(){assertFalse(ReleaseNotesPolicy.shouldShow(100,100,58,0));assertTrue(ReleaseNotesPolicy.shouldShow(100,200,58,57));assertFalse(ReleaseNotesPolicy.shouldShow(100,200,58,58));}
 @Test public void litresFeedIsAudioOnlyAndDateMustBelongToTheAudioEdition(){String url="https://www.litres.ru/audiobook/test-writer/new-book-123/";String cards="<h1>Новые аудиокниги</h1><div data-testid='art__wrapper'><a data-testid='art__title' href='"+url+"'>Новая книга</a><a data-testid='art__authorName--link'>Тест Автор</a></div><div data-testid='art__wrapper'><a data-testid='art__title' href='/book/test-writer/text-book-125/'>Текст</a><a data-testid='art__authorName--link'>Тест Автор</a></div>";assertEquals(1,LitresReleaseParser.feed(cards).size());String audio="<h1>Новая книга</h1><a data-testid='book__author--link'>Тест Автор</a><div><div>Дата выхода на Литрес: </div><span>25 октября 2026</span></div>";long d=LitresReleaseParser.releaseDate(audio,url,"Новая книга","Тест Автор");assertTrue(d>0);assertEquals(0,LitresReleaseParser.releaseDate(audio,url.replace("/audiobook/","/book/"),"Новая книга","Тест Автор"));assertTrue(LitresReleaseParser.newlyReleased(d,d+100,d+200));assertFalse(LitresReleaseParser.newlyReleased(d,d+86400000,d+90000000));assertFalse(LitresReleaseParser.newlyReleased(d,0,d+200));assertFalse(LitresReleaseParser.newlyReleased(d,d-100,d-1));}
}
